vec3 palette( float t) {
    vec3 a = vec3(0.5);
    vec3 b = vec3(0.5);
    vec3 c = vec3(1.0);
    vec3 d = vec3(-0.1, 0.13, 0.23f);

    return a + b*cos(6.28318*(c*t+d) );
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
   vec2 uv0 = uv;
   vec3 finalColor = vec3(1.);
   float imax = 4.;
   for (float i = 0.0; i <= imax; i+=1.) {

       uv = fract(uv * 1.4) - .5;

       float d = length(uv) * exp(-length(uv0 * i *0.1));

       vec3 col = palette(i/imax);

       d = sin(d * 8. + iTime*2.)/8.;

       if (d > 0.05 && d < 0.1) finalColor = col ;
   }

   finalColor.x = pow(finalColor.x, 0.5);
   finalColor.y = pow(finalColor.y, 2.);
   finalColor.z = pow(finalColor.z, 2.0);

   fragColor = vec4(finalColor,1.0);
}
